import{z as d,x as c,o as a,c as E,q as r,j as n,D as o,d as l,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"vLLM V1 架构","description":"","frontmatter":{"title":"vLLM V1 架构","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vllm-v1.md","filePath":"llm/vllm-v1.md","lastUpdated":1791063341000}'),p={name:"llm/vllm-v1.md"};function A(h,e,m,P,u,_){const t=c("Mermaid");return a(),E("div",null,[e[2]||(e[2]=r('<h1 id="vllm-v1-架构" tabindex="-1">vLLM V1 架构 <a class="header-anchor" href="#vllm-v1-架构" aria-label="Permalink to &quot;vLLM V1 架构&quot;">​</a></h1><div class="epigraph"><p>调度器不再区分前填与解码阶段，只给出「这条请求本步算几个 token」；API 进程与 EngineCore 拆开，CPU 上的分词与 GPU 上的一步前向重叠。</p><footer>—— vLLM 项目组，vLLM V1: A Major Upgrade to vLLM&#39;s Core Architecture，2025-01-27</footer></div><p>SOSP 2023 的 vLLM 把控制面收成中央调度器、KV 块管理器、worker 与 PagedAttention，见 <a href="/llm/vllm-architecture">架构</a> 与 <a href="/llm/vllm-paper">论文</a>。那条脊梁在 V0 里逐渐被特性堆成难以改动的阶段机：前填/解码分叉、chunked prefill、前缀缓存、投机解码各走一套调度分支。V1（2025 年 1 月博客，随后成为默认引擎）重写调度器、KV 管理器、worker、采样器与 API 服务，但<strong>复用</strong> V0 的模型实现、GPU 核、分布式控制面。本篇写 V1 相对 V0 改了哪一层进程模型与调度表示，不把分页公式再推导一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">「GIL」是 Python 的全局解释器锁：同一进程里同一时刻只有一个线程在执行 Python 字节码。分词、预处理和调度循环抢 GIL，就是抢「谁能让 Python 动起来」——V1 的解法不是抢锁更快，而是把这些活拆到不同进程，让锁不再串起同一条时间轴。</span></p><p>V0 的 Python 路径上，AsyncLLM、分词、多模态预处理、反分词和流式发送与调度循环抢同一把 GIL。v0.6.0 已经用 ZeroMQ 把 HTTP API 进程拆出去，V1 要把这条多进程边界推进到引擎内部：真正的一步前向只留在 <code>EngineCore</code> 里，前端 CPU 工作与之重叠。否则核再快，调度与取样的 Python 尾巴仍会在短解码上露出来。</p><p>第二问题是调度表示。把请求标成「正在 prefill」或「正在 decode」，每加一个特性就要在两支上复制逻辑。<a href="/llm/chunked-prefill">Chunked prefill</a> 要的是「这次只算提示的 \\(C\\) 个 token」；前缀缓存要的是「跳过 \\(m\\) 个已命中 token」；投机解码要的是「一次提交 \\(k\\) 个草稿 token」。它们其实都是同一句话：本步每条请求的 token 预算。V0 用阶段机表达，V1 改用一张字典。</p><h3 id="统一调度不是取消前填的屋顶线" tabindex="-1">统一调度不是取消前填的屋顶线 <a class="header-anchor" href="#统一调度不是取消前填的屋顶线" aria-label="Permalink to &quot;统一调度不是取消前填的屋顶线&quot;">​</a></h3><p>前填仍然算力密、解码仍然带宽密，见 <a href="/llm/prefill-compute">Prefill 计算特征</a>。V1 只是不再用阶段标签驱动控制流。硬件画像还在：token 预算过大，一步里塞进超长提示，ITL 会抖；预算过小，GEMM 变瘦。统一表示让 chunked prefill 变成「在 <code>max_num_batched_tokens</code> 下给各请求切额度」，而不是另写一套阶段调度器。</p><p><span class="marginnote">博客写明 V1 与 V0 共享核与模型实现。基准上若只换 V1 开关、核版本没变，加速主要来自调度与 CPU 重叠，不是 FlashAttention 突然换代。把 V1 说成「新的注意力算法」是错层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进程角色拆成四类。<strong>API Server</strong>：HTTP、分词、多模态加载、反分词、流式。<strong>EngineCore</strong>：只跑调度与执行循环，从输入队列取新请求，每步 <code>schedule</code> 再 <code>execute</code>。<strong>GPU worker</strong>：模型前向，与 V0 一样按 TP/PP 切。<strong>DP coordinator</strong>（数据并行时）：在多个 EngineCore 之间做内部负载均衡。API 与 Core 之间走 ZeroMQ；官方架构概述写成多 API 对多 Core 的网，任一前端可以把请求送到某个引擎。<code>AsyncLLM</code> 仍在前端进程里用 asyncio，但 GIL 不再挡住 Core 的一步。</p><p><span class="marginnote">直觉类比餐厅传菜单：调度器每轮只看「每桌本步做几道菜」（<code>{request_id: num_tokens}</code>），不问这桌是刚开始点单（prefill）还是加菜（decode）——在后厨眼里点单和加菜都是「要做几道」。V0 的阶段机则要先问「这桌处于哪个阶段」再走不同流程。</span></p><p>调度器的输出是 <code>{request_id: num_tokens}</code>：本步每条请求处理多少 token。提示 token 与已生成 token 同等看待。固定 token 预算下，长提示被切成多步（chunked prefill），短解码可以和一块前填拼在同一步。前缀缓存默认纳入这条路径：命中的前缀不占本步预算。投机解码把草稿长度写成更大的 <code>num_tokens</code>。博客认为这张表足够覆盖上述特性，从而删掉 V0 里分叉的阶段逻辑。</p><p>KV 管理器仍按块分配，但与统一调度对齐：额度是 token 数，换算成块数在管理器里做。前缀缓存在 V1 里是一等公民，而不再是后挂的可选路径。采样器、投机逻辑随 Core 重写，以便和「一步多 token」的表示一致。启用方式在 alpha 期是 <code>VLLM_USE_V1=1</code>；随后版本改为默认 V1，V0 逐步退出。</p>',15)),(a(),n(i,null,{default:o(()=>[s(t,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20HTTP%5B%22API%20Server%EF%BC%9A%E5%88%86%E8%AF%8D%20%2F%20%E6%B5%81%E5%BC%8F%22%5D%20--%3E%7C%22ZeroMQ%22%7C%20EC%5B%22EngineCore%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20EC%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%EF%BC%9Arequest_id%20%E2%86%92%20num_tokens%22%5D%0A%20%20SCH%20--%3E%20EX%5B%22Executor%20%2F%20GPU%20Worker%22%5D%0A%20%20EX%20--%3E%20KV%5B%22%E5%9D%97%E8%A1%A8%20KV%20%E7%AE%A1%E7%90%86%E5%99%A8%22%5D%0A%20%20EX%20--%3E%20SMP%5B%22%E9%87%87%E6%A0%B7%E5%99%A8%22%5D%0A%20%20SMP%20--%3E%20EC%0A%20%20EC%20--%3E%20HTTP%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<h3 id="异步调度把「下一步」叠进「这一步」的计算" tabindex="-1">异步调度把「下一步」叠进「这一步」的计算 <a class="header-anchor" href="#异步调度把「下一步」叠进「这一步」的计算" aria-label="Permalink to &quot;异步调度把「下一步」叠进「这一步」的计算&quot;">​</a></h3><p>后续 PR（如 vLLM#19970）引入 <code>AsyncScheduler</code>：调度领先执行一步，用占位输出表示「已调度、尚未生成」的 token，使调度开销与模型前向重叠。思路与 NanoFlow（Zhu et al., arXiv:2408.12757）同类。<code>max_concurrent_batches</code> 提到 2，意味着执行侧可能同时有一批在算、一批已规划。这不是 SOSP 论文的贡献，也不是 V1 alpha 博客的全部内容，但它是 V1 表示变薄之后才容易做的叠加。打开 <code>--async-scheduling</code> 要接受：块的分配与缓存插入推迟到结果返回，排障时「调度器以为已写入」与「核尚未写完」会短暂不一致。</p><p>Ubicloud 等对 V1 请求生命周期的拆解与官方概述一致：Core 内部还有把 ZeroMQ 字节搬进输入队列、把输出队列搬回 IPC 的后台线程。忙循环本身只做「取新请求 → 调度 → 执行 → 回送」。把这些后台线程画进架构图，是为了避免误以为 ZeroMQ 收发发生在 GPU 流上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CPU/GPU 重叠的机制是进程隔离。分词与多模态预处理在 API 进程跑的时候，Core 可以正在跑上一步的 GEMM。GIL 不再把两边串成一条 Python 时间轴。吞吐收益在「核已经很快、CPU 尾巴可见」的短上下文、高 QPS 场景最大；超长前填时核本身是墙，拆进程帮不上二次注意力。</p><p>统一 token 预算的机制是把混合批写成资源分配。一步的成本大致随本步 token 数（前填段）和解码条数（读权重）变化。调度器不必先决定「这一步是前填步还是解码步」，只需在预算内塞请求。这简化了代码，也把策略暴露成可调的 <code>max_num_batched_tokens</code>：运维调的是预算，不是阶段开关。公平性仍要另写——预算可以被长提示一次吃满，V1 并不自动等于 stall-free，chunk 大小与预算要一起设。</p><p>三个特性如何被同一个调度表示覆盖，一张图就能对上：</p>',7)),(a(),n(i,null,{default:o(()=>[s(t,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22%E7%BB%9F%E4%B8%80%20token%20%E9%A2%84%E7%AE%97%22%5D%20--%3E%20C1%5B%22chunked%20prefill%20%E6%9C%AC%E6%AD%A5%E5%8F%AA%E7%AE%97%20C%20%E4%B8%AA%E6%8F%90%E7%A4%BA%20token%22%5D%0A%20%20B%20--%3E%20C2%5B%22%E5%89%8D%E7%BC%80%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%E7%9A%84%20m%20%E4%B8%AA%E4%B8%8D%E5%8D%A0%E9%A2%84%E7%AE%97%22%5D%0A%20%20B%20--%3E%20C3%5B%22%E6%8A%95%E6%9C%BA%E8%A7%A3%E7%A0%81%E4%B8%80%E6%AD%A5%E6%8F%90%E4%BA%A4%20k%20%E4%B8%AA%E8%8D%89%E7%A8%BF%22%5D%0A%20%20C1%20--%3E%20OUT%5B%22%E8%B0%83%E5%BA%A6%E8%A1%A8%20request_id%20%E5%88%B0%20num_tokens%22%5D%0A%20%20C2%20--%3E%20OUT%0A%20%20C3%20--%3E%20OUT%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<p><span class="marginnote">数字实例：预算 <code>max_num_batched_tokens=8192</code> 时，一条 20000 token 的长提示会被切成约 3 步（8192、8192、3616），decode 请求在每步剩余额度里插空执行——这就是 chunked prefill「保护 ITL」的具体机制，不需要单独的阶段调度器。</span></p><p><span class="marginnote">V1 默认打开前缀缓存，改变的是空载时的 CPU 与内存记账，不是「所有负载都更快」。无共享流量上，缓存插入与淘汰是额外工作；有共享时，少做的前填才是收益。对照实验必须声明是否关闭缓存。</span></p><h3 id="和-sosp-架构图的关系" tabindex="-1">和 SOSP 架构图的关系 <a class="header-anchor" href="#和-sosp-架构图的关系" aria-label="Permalink to &quot;和 SOSP 架构图的关系&quot;">​</a></h3><p>Kwon 等人的四件套仍然在：调度器、KV 管理器、worker、分页核。V1 改的是调度器的<strong>接口形状</strong>和它们所在的<strong>进程</strong>。张量并行下仍是一个 Core 对齐所有 worker 的同一步；多副本是多套 Core，中间多一个 DP coordinator。不要把 V1 画成「没有中央调度器」——Core 就是中央循环，只是不再和 FastAPI 住在一起。分离式 PD、Mooncake 连接器、LMCache 是接在这套循环之外的角色，属于后续插件，不应写回 2025-01 博客的贡献表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>V1 alpha 期间功能覆盖落后于 V0：部分采样参数、偏门解码、某些硬件插件是后来才迁完的。生产要以当时发行说明为准，而不是假设「架构更干净所以功能超集」。多进程调试更难：请求卡在 API、卡在 IPC、还是卡在 Core 队列，日志要带同一 <code>request_id</code> 才能对上。</p><p>异步调度与投机、约束解码、水印钩子的组合会放大「占位 token」语义：水印和文法掩码必须作用在真实 logits 上，不能作用在占位符。图捕获、CUDA Graph 的形状因一步 token 数变化而更难固定——统一调度让一步的形状更动态，这是灵活性的代价。数据并行内部负载均衡若只看队列长度、不看前缀，会打穿 V1 默认打开的前缀缓存；集群入口应配合 <a href="/llm/sglang-router">SGLang Router</a> 或 Dynamo Smart Router 一类缓存感知路由。</p><p><span class="marginnote">出处钉 vLLM 博客 <em>vLLM V1: A Major Upgrade to vLLM&#39;s Core Architecture</em>（2025-01-27，<a href="https://vllm.ai/blog/2025-01-27-v1-alpha-release%EF%BC%89%E4%B8%8E%E6%96%87%E6%A1%A3" target="_blank" rel="noreferrer">https://vllm.ai/blog/2025-01-27-v1-alpha-release）与文档</a> Architecture Overview。分页与利用率数字仍引用 Kwon et al., SOSP 2023（arXiv:2309.06180）。异步调度另见 vLLM PR 19970 与 NanoFlow arXiv:2408.12757。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>V1 重写调度器与进程模型，核与模型实现继承 V0；脊梁仍是中央调度 + 分页 KV + worker。</li><li>调度表示是 <code>{request_id: num_tokens}</code>，chunked prefill、前缀缓存、投机解码都映射到 token 额度。</li><li>API 进程与 EngineCore 经 ZeroMQ 隔离，分词/流式与一步前向重叠，躲开 GIL。</li><li>异步调度让规划领先执行一步；排障要区分占位与已写入的 KV。</li><li>加速来自 CPU 重叠与更简单的混合批，不来自新的注意力公式。</li><li>出处：vLLM V1 博客与架构文档；SOSP 2023 论文描述的是被 V1 继承的分页脊梁。</li></ul>',10))])}const V=d(p,[["render",A]]);export{C as __pageData,V as default};
